var PM=[[1,0],[-1,0],[0,1],[0,-1]];
function gridMap(n){ var g={}; for(var i=0;i<n.length;i++) g[n[i][0]+','+n[i][1]]=i; return g; }
function countContacts(n, seq){ var g=gridMap(n); var c=0;
  for(var i=0;i<n.length;i++){ if(seq[i]!=='H') continue; var p=n[i];
    for(var t=0;t<4;t++){ var key=(p[0]+PM[t][0])+','+(p[1]+PM[t][1]); if(g[key]!==undefined){ var j=g[key];
      if(j!==i && j!==i-1 && j!==i+1 && seq[j]==='H') c++; } } }
  return c/2; }
function foldHP(seq, limit){ limit=limit||200000; var used={}; var nodes=[[0,0]]; used['0,0']=1;
  var best={energy:0, path:null}; var cnt=0;
  function back(k){ if(cnt>limit) return; cnt++;
    if(k===seq.length){ var e=-countContacts(nodes,seq); if(e<=best.energy){ best={energy:e, path:nodes.map(function(p){return [p[0],p[1]];})}; } return; }
    var last=nodes[nodes.length-1];
    for(var d=0;d<4;d++){ var nx=last[0]+PM[d][0], ny=last[1]+PM[d][1], key=nx+','+ny;
      if(used[key]) continue; used[key]=1; nodes.push([nx,ny]); back(k+1); nodes.pop(); delete used[key]; } }
  if(seq.length>0) back(1);
  return best;
}
var EXPORTS={foldHP:foldHP, countContacts:countContacts};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ProteinFoldForgePure = EXPORTS; }
